
public class ex3_b {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int n=5;
		int v=5;
		
				
		
		for(int l=1; l<=n; l++) {
			for(int c=1; c<=n; c++)
			{
				 if (c>=l)
				 {
					System.out.print(v);
								
				}
				
			}
			v--;
			System.out.print("\n");
		}
		
		
	}

}
